  const needPx = Math.round(CARD_RIGHT + (col ? 0 : CARD_W * SCALE) + room);
  manageRoom(g, true, needPx, col ? 0 : CANDLE_RIGHT); // in the column no cards on the chart: only the chosen space

  const eb = m.eqBar || {};
  els.acc.textContent = eb.account || '';

