    const tgTxt = (t) => (t.by === 'trail' ? `T${t.n} trailing ×${F.qty(t.qty)}` : Number.isFinite(t.price) ? `T${t.n} <b>${fp(t.price)}</b> ×${F.qty(t.qty)}` : `T${t.n} —`);
