    out.createOrderLine = typeof c.createOrderLine === 'function';
    out.createPositionLine = typeof c.createPositionLine === 'function';
    out.crossHairMoved = typeof c.crossHairMoved === 'function';
    out.symbol = typeof c.symbol === 'function';
