    ...pos.map((p) => `${p.side === 'long' ? 'LONG' : 'SHORT'} ${p.qty} ${sym(p.symbol)}`),
    ...ord.map((o) => `pending ${o.side === 'long' ? 'BUY' : o.side === 'short' ? 'SELL' : '?'} ${o.qty} ${sym(o.symbol)} @ ${o.price}`),
